 const { chromium } = require('playwright');
 const fs = require('fs');
 const path = require('path');

 (async () => {
   let browser;
   try {
     browser = await chromium.launch();
     const page = await browser.newPage();

     // Log console messages from the page
     page.on('console', msg => console.log('PAGE LOG:', msg.text()));
     page.on('pageerror', err => console.log('PAGE ERROR:', err.message));

     const filePath = 'file://' + path.resolve('index.html');
     await page.goto(filePath);

     // Wait for Babel and React
     await page.waitForTimeout(5000);

     const content = await page.content();
     console.log('Page content length:', content.length);
     console.log('Root innerHTML:', await page.innerHTML('#root'));

     const axeSource = fs.readFileSync(require.resolve('axe-core/axe.min.js'), 'utf8');
     await page.addScriptTag({ content: axeSource });

     const results = await page.evaluate(async () => {
       return await window.axe.run();
     });

     const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
     const bp = results.violations.filter(v => v.tags.includes('best-practice'));

     console.log(JSON.stringify({
       wcag: wcag.map(v => ({ id: v.id, impact: v.impact, help: v.help, targets: v.nodes.map(n => n.target) })),
       bp: bp.map(v => ({ id: v.id, help: v.help, targets: v.nodes.map(n => n.target) }))
     }, null, 2));

     process.exit(wcag.length > 0 ? 1 : 0);
   } catch (err) {
     console.error(err);
     process.exit(1);
   } finally {
     if (browser) await browser.close();
   }
 })();

